/**
 * This-turn Slack posts. `reserve` is the ts `post-update` returns.
 * `bind` attaches the Slack ts after `chat.postMessage`. `has` is either.
 * `lastPostAt` is the quiet clock: turn start, then each `post-update`.
 */
export const SLACK_QUIET_MS = 90_000;
export const SLACK_QUIET_HINT = "<slack_quiet>Thread has been quiet. post-update if the picture changed (dead-end, widen, or breakthrough).</slack_quiet>";
const posted = new Map();
function empty(now = Date.now()) {
    return {
        n: 0,
        reserved: new Set(),
        slack: new Map(),
        text: new Map(),
        lastPostAt: now,
    };
}
function turn(sessionId) {
    let current = posted.get(sessionId);
    if (current === undefined) {
        current = empty();
        posted.set(sessionId, current);
    }
    return current;
}
export function begin(sessionId, now = Date.now()) {
    posted.set(sessionId, empty(now));
}
export function end(sessionId) {
    posted.delete(sessionId);
}
export function reserve(sessionId, now = Date.now()) {
    const current = turn(sessionId);
    current.n += 1;
    current.lastPostAt = now;
    const ts = String(current.n);
    current.reserved.add(ts);
    return ts;
}
export function appendSlackQuietHint(sessionId, result, now = Date.now()) {
    if (result.isError === true) {
        return result;
    }
    const current = posted.get(sessionId);
    if (current === undefined || now - current.lastPostAt < SLACK_QUIET_MS) {
        return result;
    }
    return {
        ...result,
        content: [...result.content, { type: "text", text: SLACK_QUIET_HINT }],
    };
}
export function bind(sessionId, ts, slackTs, text) {
    const current = turn(sessionId);
    current.reserved.delete(ts);
    current.slack.set(ts, slackTs);
    current.slack.set(slackTs, slackTs);
    current.text.set(slackTs, text);
}
export function setPostedText(sessionId, slackTs, text) {
    posted.get(sessionId)?.text.set(slackTs, text);
}
export function has(sessionId, ts) {
    const current = posted.get(sessionId);
    return current !== undefined && (current.reserved.has(ts) || current.slack.has(ts));
}
export function resolve(sessionId, ts) {
    return posted.get(sessionId)?.slack.get(ts);
}
export function remove(sessionId, ts) {
    const current = posted.get(sessionId);
    if (current === undefined) {
        return;
    }
    current.reserved.delete(ts);
    const slackTs = current.slack.get(ts) ?? ts;
    current.text.delete(slackTs);
    for (const [key, value] of current.slack) {
        if (key === ts || key === slackTs || value === slackTs) {
            current.slack.delete(key);
        }
    }
}
export function latest(sessionId) {
    const current = posted.get(sessionId);
    if (current === undefined || current.slack.size === 0) {
        return undefined;
    }
    return [...current.slack.values()].at(-1);
}
export function latestPosted(sessionId) {
    const ts = latest(sessionId);
    if (ts === undefined) {
        return undefined;
    }
    const text = posted.get(sessionId)?.text.get(ts);
    if (text === undefined || text === "") {
        return undefined;
    }
    return { ts, text };
}
